function getEmployeeDialogue(role: string): string {
  const key = role.toLowerCase();
  const lines = EMPLOYEE_DIALOGUE[key] ?? EMPLOYEE_DIALOGUE.default;
  return lines[Math.floor(Math.random() * lines.length)];
}

