function defaultAppearance(charClass?: string): Appearance {
  const cls = (charClass ?? '').toLowerCase();
  const outfitStyle: OutfitStyle =
    cls === 'corporate' ? 'suit' :
    cls === 'outlaw'    ? 'duster' :
    cls === 'replicant' ? 'hoodie' : 'casual';
  const outfitColor =
    cls === 'corporate' ? '#2e2e2e' :
    cls === 'outlaw'    ? '#6b4a28' :
    cls === 'replicant' ? '#3a4a5a' : '#556644';
  return {
    gender: 'nb',
    skinTone: '#d4906a',
    hairColor: '#1a1a1a',
    hairStyle: 'short',
    faceStyle: 'plain',
    outfitStyle,
    outfitColor,
  };
}

// Draws the player's hair on top of the head. Hair geometry sits at
// the same offsets the previous hardcoded "slick cut" used so the
// existing class outlines (corporate glasses, outlaw hat, etc.) still
// line up. Coords passed are the sprite anchor (head-center, foot Y).
function drawPlayerHair(
  ctx: CanvasRenderingContext2D,
  cx: number,
  py2: number,
  style: HairStyle,
  hairCol: string,
): void {
  if (style === 'bald') return;
  ctx.fillStyle = hairCol;
  if (style === 'short') {
    ctx.fillRect(cx - 4, py2 - 19, 8, 4);
    ctx.beginPath(); ctx.arc(cx, py2 - 18, 3, Math.PI, 0); ctx.fill();
  } else if (style === 'long') {
    ctx.fillRect(cx - 4, py2 - 19, 8, 4);
    ctx.beginPath(); ctx.arc(cx, py2 - 18, 3, Math.PI, 0); ctx.fill();
    // Hair flowing past shoulders
    ctx.fillRect(cx - 5, py2 - 16, 2, 7);
    ctx.fillRect(cx + 3, py2 - 16, 2, 7);
  } else if (style === 'mohawk') {
    ctx.fillRect(cx - 1, py2 - 22, 2, 8);
    ctx.fillRect(cx - 4, py2 - 17, 8, 2);
  } else if (style === 'bun') {
    ctx.fillRect(cx - 4, py2 - 18, 8, 3);
    ctx.beginPath(); ctx.arc(cx, py2 - 21, 2.5, 0, Math.PI * 2); ctx.fill();
  } else if (style === 'bowl') {
    ctx.fillRect(cx - 5, py2 - 19, 10, 5);
    ctx.fillRect(cx - 4, py2 - 14, 8, 1);
  }
}

// Face overlay (drawn after eyes/mouth so it sits on top).
function drawPlayerFace(
  ctx: CanvasRenderingContext2D,
  cx: number,
  py2: number,
  style: FaceStyle,
): void {
  if (style === 'plain') return;
  if (style === 'shades') {
    ctx.fillStyle = '#0a0a0a';
    ctx.fillRect(cx - 4, py2 - 16, 8, 2);
    ctx.fillStyle = 'rgba(255,255,255,0.18)';
    ctx.fillRect(cx - 3, py2 - 16, 1, 1);
    ctx.fillRect(cx + 2, py2 - 16, 1, 1);
  } else if (style === 'visor') {
    ctx.fillStyle = '#56e8ff';
    ctx.shadowColor = '#56e8ff'; ctx.shadowBlur = 4;
    ctx.fillRect(cx - 4, py2 - 16, 8, 2);
    ctx.shadowBlur = 0;
  } else if (style === 'scar') {
    ctx.strokeStyle = '#a83020'; ctx.lineWidth = 0.8;
    ctx.beginPath();
    ctx.moveTo(cx - 3, py2 - 16);
    ctx.lineTo(cx - 1, py2 - 11);
    ctx.stroke();
  } else if (style === 'beard') {
    ctx.fillStyle = '#1a1208';
    ctx.fillRect(cx - 3, py2 - 12, 6, 2);
    ctx.fillRect(cx - 4, py2 - 12, 1, 1);
    ctx.fillRect(cx + 3, py2 - 12, 1, 1);
  } else if (style === 'cyber') {
    // Glowing red right eye (Pablo would approve)
    ctx.fillStyle = '#ff2244';
    ctx.shadowColor = '#ff2244'; ctx.shadowBlur = 4;
    ctx.fillRect(cx + 2, py2 - 15, 1, 1);
    ctx.shadowBlur = 0;
  }
}

// Draws the distinguishing accents for the equipped costume STYLE on top of the
// already-rendered class silhouette. The body colour itself comes from the
// costume (CLOTHES.color via costumeColor); this layer adds the small details
// that make a SUIT read differently from PUNK, GOTH, CYBER PUNK, etc. Anchored
// to the torso top (py2-8) and offset by the iso lean like the rest of the body.
function drawCostumeAccents(
  ctx: CanvasRenderingContext2D,
  px: number,
  py2: number,
  idleBob: number,
  lx: number,
  style: string,
  accent: string,
): void {
  const tY = py2 - 8 + idleBob; // torso top
  if (style === 'suit') {
    ctx.fillStyle = '#e8e8e8'; ctx.fillRect(px - 1 + lx, tY + 1, 2, 2);
    ctx.fillStyle = accent; ctx.fillRect(px - 1 + lx, tY + 2, 2, 5);
  } else if (style === 'pant_suit') {
    ctx.fillStyle = accent; ctx.fillRect(px - 4 + lx, tY, 2, 4); ctx.fillRect(px + 3 + lx, tY, 2, 4);
    ctx.fillStyle = '#f0f0f0'; ctx.fillRect(px - 1 + lx, tY + 1, 2, 3);
  } else if (style === 'business_casual') {
    ctx.fillStyle = accent; ctx.fillRect(px - 2 + lx, tY, 4, 3);
    ctx.fillStyle = '#2a4038'; ctx.fillRect(px - 3 + lx, tY, 1, 2); ctx.fillRect(px + 2 + lx, tY, 1, 2);
  } else if (style === 'punk') {
    // shoulder spikes + safety-pin chest line
    ctx.fillStyle = accent;
    ctx.fillRect(px - 6 + lx, tY, 1, 1); ctx.fillRect(px + 5 + lx, tY, 1, 1);
    ctx.fillRect(px - 5 + lx, tY - 1, 1, 1); ctx.fillRect(px + 4 + lx, tY - 1, 1, 1);
    ctx.fillRect(px - 3 + lx, tY + 3, 6, 1);
  } else if (style === 'rocker') {
    // open leather zipper + red lining + chrome studs
    ctx.fillStyle = accent; ctx.fillRect(px - 1 + lx, tY, 1, 7);
    ctx.fillStyle = '#3a3a3a'; ctx.fillRect(px - 4 + lx, tY, 1, 6); ctx.fillRect(px + 3 + lx, tY, 1, 6);
    ctx.fillStyle = '#cccccc'; ctx.fillRect(px - 5 + lx, tY, 1, 1); ctx.fillRect(px + 4 + lx, tY, 1, 1);
  } else if (style === 'goth') {
    // high black collar + accent + silver chain
    ctx.fillStyle = '#0a0a0f'; ctx.fillRect(px - 3 + lx, tY - 1, 6, 2);
    ctx.fillStyle = accent; ctx.fillRect(px - 2 + lx, tY + 1, 4, 1);
    ctx.fillStyle = '#c0c0d0'; ctx.fillRect(px - 1 + lx, tY + 4, 2, 1);
  } else if (style === 'wasteland') {
    // diagonal strap + patch
    ctx.fillStyle = accent;
    ctx.fillRect(px - 4 + lx, tY + 1, 2, 1); ctx.fillRect(px - 2 + lx, tY + 3, 2, 1); ctx.fillRect(px + 0 + lx, tY + 5, 2, 1);
    ctx.fillStyle = '#9a8a5a'; ctx.fillRect(px + 2 + lx, tY + 2, 2, 2);
  } else if (style === 'cyberpunk') {
    // glowing neon circuitry
    ctx.shadowColor = accent; ctx.shadowBlur = 4; ctx.fillStyle = accent;
    ctx.fillRect(px - 5 + lx, tY + 6, 10, 1);
    ctx.fillRect(px - 4 + lx, tY, 1, 7); ctx.fillRect(px + 3 + lx, tY, 1, 7);
    ctx.shadowBlur = 0;
  } else if (style === 'solarpunk') {
    // gold solar trim + leaf shoulder + sun emblem
    ctx.fillStyle = accent; ctx.fillRect(px - 5 + lx, tY + 6, 10, 1);
    ctx.fillStyle = '#3fbf6f'; ctx.fillRect(px + 4 + lx, tY - 1, 2, 1); ctx.fillRect(px + 5 + lx, tY - 2, 1, 1);
    ctx.fillStyle = accent; ctx.fillRect(px - 1 + lx, tY + 1, 2, 1);
  }
}

// ── Equipped Armory gear, rendered ON the avatar ──────────────────────────────
// The Armory persists a loadout (weapon / armor / outfit / vehicle / …) server
// side; WorldPlay loads the SAME /api/items/loadout the combat stats come from
// and resolves each equipped item's visual descriptor into this shape. The
// helpers below paint that gear onto the player sprite so the investment is
// visible in the world (and to other players), never recomputing anything the
// catalog already knows.
interface EquippedGearVisual {
  id: string;
  type: string;
  vehicleKind?: string;
  rarity: string;
}

const GEAR_RARITY_COLOR: Record<string, string> = {
  common: '#94a3b8',
  expensive: '#34d399',
  rare: '#38bdf8',
  very_rare: '#a78bfa',
  legendary: '#fbbf24',
};
const gearRarityColor = (rarity?: string): string => GEAR_RARITY_COLOR[rarity ?? ''] ?? '#94a3b8';
// Higher-tier gear earns a soft glow; common/expensive stay matte.
const gearGlow = (rarity?: string): number =>
  rarity === 'legendary' ? 6 : rarity === 'very_rare' ? 4 : rarity === 'rare' ? 3 : 0;

// Outfit (clothes slot) — recolours the torso/shoulders with a rarity-tinted
// mantle + collar so an Executive Power Suit reads differently from a Jumpsuit.
function drawGearOutfit(
  ctx: CanvasRenderingContext2D, px: number, py2: number, idleBob: number, lx: number, gear: EquippedGearVisual,
): void {
  const col = gearRarityColor(gear.rarity);
  const tY = py2 - 8 + idleBob;
  const glow = gearGlow(gear.rarity);
  if (glow) { ctx.shadowColor = col; ctx.shadowBlur = glow; }
  // Shoulder mantle
  ctx.fillStyle = col;
  ctx.fillRect(px - 6 + lx, tY, 3, 2);
  ctx.fillRect(px + 3 + lx, tY, 3, 2);
  // Collar / lapel trim
  ctx.fillRect(px - 5 + lx, tY, 1, 4);
  ctx.fillRect(px + 4 + lx, tY, 1, 4);
  ctx.shadowBlur = 0;
}

// Armor (armor slot) — a metallic chest plate + pauldrons layered over the body.
function drawGearArmor(
  ctx: CanvasRenderingContext2D, px: number, py2: number, idleBob: number, lx: number, gear: EquippedGearVisual,
): void {
  const col = gearRarityColor(gear.rarity);
  const tY = py2 - 8 + idleBob;
  const glow = gearGlow(gear.rarity);
  if (glow) { ctx.shadowColor = col; ctx.shadowBlur = glow; }
  // Chest plate
  ctx.fillStyle = '#9aa3ad';
  ctx.fillRect(px - 3 + lx, tY + 1, 6, 6);
  // Plate highlight + rarity-tinted ridge
  ctx.fillStyle = '#cdd4dc';
  ctx.fillRect(px - 3 + lx, tY + 1, 6, 1);
  ctx.fillStyle = col;
  ctx.fillRect(px - 1 + lx, tY + 2, 2, 4);
  // Pauldrons
  ctx.fillStyle = '#7b828c';
  ctx.fillRect(px - 6 + lx, tY, 2, 2);
  ctx.fillRect(px + 4 + lx, tY, 2, 2);
  ctx.shadowBlur = 0;
}

// Weapon (weapon slot) — the equipped Armory weapon, drawn in the player's hand
// when no combat weapon is wielded, otherwise slung across the back so it stays
// visible without ever double-drawing over the active in-hand weapon.
function drawGearWeapon(
  ctx: CanvasRenderingContext2D, px: number, py2: number, idleBob: number, rArm: number,
  facing: 'right' | 'left' | 'up' | 'down', inHand: boolean, gear: EquippedGearVisual,
): void {
  const col = gearRarityColor(gear.rarity);
  const glow = gearGlow(gear.rarity);
  const dir = facing === 'right' ? 1 : facing === 'left' ? -1 : 0;
  if (inHand) {
    const hx = facing === 'right' ? px + 10 : facing === 'left' ? px - 10 : px + 9;
    const hy = py2 - 6 + idleBob + rArm;
    if (glow) { ctx.shadowColor = col; ctx.shadowBlur = glow; }
    switch (gear.id) {
      case 'wpn_briefcase':
        ctx.fillStyle = '#5a3a1a'; ctx.fillRect(hx - 1, hy, 4, 5);
        ctx.fillStyle = '#caa15a'; ctx.fillRect(hx - 1, hy + 1, 4, 1); break;
      case 'wpn_bat':
        ctx.strokeStyle = '#b0b0b8'; ctx.lineWidth = 3; ctx.beginPath();
        ctx.moveTo(hx, hy + 2); ctx.lineTo(hx + dir * 11, hy - 6); ctx.stroke(); break;
      case 'wpn_katana':
        ctx.strokeStyle = '#aaccee'; ctx.lineWidth = 2; ctx.beginPath();
        ctx.moveTo(hx, hy); ctx.lineTo(hx + (dir || 0.15) * 14, hy - 10); ctx.stroke();
        ctx.fillStyle = '#664433'; ctx.fillRect(hx - 1, hy, 2, 5); break;
      case 'wpn_smg':
        ctx.fillStyle = '#556677'; ctx.fillRect(dir >= 0 ? hx : hx - 9, hy - 2, 9, 4);
        ctx.fillStyle = '#33414f'; ctx.fillRect(dir >= 0 ? hx + 2 : hx - 4, hy + 2, 2, 3); break;
      case 'wpn_railgun':
        ctx.fillStyle = '#3a4658'; ctx.fillRect(dir >= 0 ? hx : hx - 13, hy - 2, 13, 5);
        ctx.fillStyle = col; ctx.fillRect(dir >= 0 ? hx + 9 : hx - 11, hy - 1, 2, 3); break;
      case 'wpn_plasma_lance':
        ctx.strokeStyle = col; ctx.lineWidth = 2.5; ctx.beginPath();
        ctx.moveTo(hx, hy + 1); ctx.lineTo(hx + (dir || 0.2) * 16, hy - 12); ctx.stroke();
        ctx.fillStyle = '#2a2a3a'; ctx.fillRect(hx - 1, hy, 2, 5); break;
      default:
        ctx.fillStyle = col; ctx.fillRect(hx - 1, hy - 4, 3, 8);
    }
    ctx.shadowBlur = 0;
  } else {
    // Slung diagonally across the back — drawn under-shoulder so the active
    // combat weapon (already rendered in-hand) reads cleanly on top.
    if (glow) { ctx.shadowColor = col; ctx.shadowBlur = glow; }
    ctx.strokeStyle = col; ctx.lineWidth = 2; ctx.beginPath();
    ctx.moveTo(px - 6, py2 - 9 + idleBob); ctx.lineTo(px + 5, py2 + 1 + idleBob); ctx.stroke();
    ctx.shadowBlur = 0;
  }
}

// Vehicle (vehicle slot) — a compact pixel mount drawn UNDER the player so the
// avatar reads as riding/driving it. Reused only for the Armory loadout vehicle;
// the existing in-world g.vehicle has its own richer sprite.
function drawGearVehicle(
  ctx: CanvasRenderingContext2D, px: number, py2: number, frame: number, gear: EquippedGearVisual,
): void {
  const kind = gear.vehicleKind ?? 'car';
  const col = gearRarityColor(gear.rarity);
  const glow = gearGlow(gear.rarity);
  const baseY = py2 + 5;
  // Shadow
  ctx.fillStyle = 'rgba(0,0,0,0.25)';
  ctx.beginPath(); ctx.ellipse(px, baseY + 4, 11, 3.5, 0, 0, Math.PI * 2); ctx.fill();
  if (glow) { ctx.shadowColor = col; ctx.shadowBlur = glow; }
  switch (kind) {
    case 'motorcycle':
    case 'speeder': {
      const hover = kind === 'speeder';
      ctx.fillStyle = hover ? '#3a4a6a' : '#883333';
      ctx.fillRect(px - 8, baseY, 16, 4);
      ctx.fillStyle = col; ctx.fillRect(px - 8, baseY, 16, 1);
      if (hover) {
        ctx.fillStyle = 'rgba(120,180,255,0.5)';
        ctx.fillRect(px - 7, baseY + 5, 14, 2);
      } else {
        ctx.fillStyle = '#111'; ctx.beginPath(); ctx.ellipse(px - 6, baseY + 5, 3, 3, 0, 0, Math.PI * 2); ctx.fill();
        ctx.beginPath(); ctx.ellipse(px + 6, baseY + 5, 3, 3, 0, 0, Math.PI * 2); ctx.fill();
      }
      break;
    }
    case 'boat': {
      ctx.fillStyle = '#6a5030'; ctx.beginPath();
      ctx.moveTo(px - 11, baseY); ctx.lineTo(px + 11, baseY);
      ctx.lineTo(px + 8, baseY + 6); ctx.lineTo(px - 8, baseY + 6); ctx.closePath(); ctx.fill();
      ctx.fillStyle = col; ctx.fillRect(px - 11, baseY, 22, 1);
      break;
    }
    case 'horse':
    case 'animal': {
      const trot = Math.sin(frame * 0.25) * 1.5;
      ctx.fillStyle = kind === 'horse' ? '#6b4a2a' : '#555';
      ctx.fillRect(px - 9, baseY, 16, 5);
      // Head
      ctx.fillRect(px + 6, baseY - 3, 4, 4);
      // Legs
      ctx.fillRect(px - 8, baseY + 5, 2, 4 + trot);
      ctx.fillRect(px - 2, baseY + 5, 2, 4 - trot);
      ctx.fillRect(px + 3, baseY + 5, 2, 4 + trot);
      ctx.fillStyle = col; ctx.fillRect(px - 9, baseY, 16, 1);
      break;
    }
    case 'flying_car': {
      ctx.fillStyle = '#445a7a'; ctx.fillRect(px - 10, baseY - 1, 20, 5);
      ctx.fillStyle = '#aaddff'; ctx.fillRect(px - 4, baseY - 3, 8, 3);
      ctx.fillStyle = 'rgba(120,180,255,0.55)'; ctx.fillRect(px - 9, baseY + 5, 18, 2);
      ctx.fillStyle = col; ctx.fillRect(px - 10, baseY - 1, 20, 1);
      break;
    }
    case 'tunneler': {
      ctx.fillStyle = '#5a5a4a'; ctx.fillRect(px - 9, baseY, 16, 6);
      // Treads
      ctx.fillStyle = '#222'; ctx.fillRect(px - 10, baseY + 5, 20, 2);
      // Drill nose
      ctx.fillStyle = col; ctx.beginPath();
      ctx.moveTo(px + 7, baseY); ctx.lineTo(px + 12, baseY + 3); ctx.lineTo(px + 7, baseY + 6); ctx.closePath(); ctx.fill();
      break;
    }
    case 'car':
    default: {
      ctx.fillStyle = '#3a4658'; ctx.fillRect(px - 10, baseY, 20, 5);
      ctx.fillStyle = '#88ccff'; ctx.fillRect(px - 5, baseY - 2, 10, 3);
      ctx.fillStyle = col; ctx.fillRect(px - 10, baseY, 20, 1);
      ctx.fillStyle = '#111';
      ctx.beginPath(); ctx.ellipse(px - 6, baseY + 5, 2.5, 2.5, 0, 0, Math.PI * 2); ctx.fill();
      ctx.beginPath(); ctx.ellipse(px + 6, baseY + 5, 2.5, 2.5, 0, 0, Math.PI * 2); ctx.fill();
      break;
    }
  }
  ctx.shadowBlur = 0;
}

function sanitizeAppearance(raw: unknown, charClass?: string): Appearance {
  const def = defaultAppearance(charClass);
  if (!raw || typeof raw !== 'object') return def;
  const r = raw as Partial<Appearance>;
  const isHex = (v: unknown): v is string => typeof v === 'string' && /^#[0-9a-fA-F]{3,8}$/.test(v);
  return {
    gender:      (['m','f','nb'] as const).includes(r.gender as Gender) ? r.gender as Gender : def.gender,
    skinTone:    isHex(r.skinTone)    ? r.skinTone    : def.skinTone,
    hairColor:   isHex(r.hairColor)   ? r.hairColor   : def.hairColor,
    hairStyle:   APPEARANCE_HAIR_STYLES.some(h => h.id === r.hairStyle) ? r.hairStyle as HairStyle : def.hairStyle,
    faceStyle:   APPEARANCE_FACE_STYLES.some(f => f.id === r.faceStyle) ? r.faceStyle as FaceStyle : def.faceStyle,
    outfitStyle: APPEARANCE_OUTFIT_STYLES.some(o => o.id === r.outfitStyle) ? r.outfitStyle as OutfitStyle : def.outfitStyle,
    outfitColor: isHex(r.outfitColor) ? r.outfitColor : def.outfitColor,
  };
}

interface Char {
  name: string; class: string; company: string; sx: number; sy: number; salary: number;
  hasBusiness?: boolean;
  bizType?: 'real' | 'minx' | 'unemployed';
  workstation?: string | null;
  workstationLabel?: string | null;
  workstationSlot?: string | null;
  bizRegisteredAt?: number | null;
  activeCostume?: string;
  ownedClothes?: string[];
  appearance?: Appearance;
}

interface QuestTask {
  id: string;
  label: string;
  done: boolean;
  mapMarker?: { x: number; y: number; label: string };
}
interface Quest {
  id: string;
  title: string;
  description: string;
  tasks: QuestTask[];
  completed: boolean;
}

const SHELTER_BUILDINGS = ['bunker', 'east_bunker', 'north_bunker', 'terminus', 'deep_bunker', 'machine_bunker'];
const CAMPSITE_IDS = ['ashfield_hostel', 'deep_camp', 'outpost_alpha', 'outpost_beta', 'supply_cache'];
const UNEMPLOYED_SPAWN_BUILDINGS = [...SHELTER_BUILDINGS, ...CAMPSITE_IDS];

function getHamletSpawn(char: Char, housingTier?: string): { x: number; y: number; buildingId: string } {
  if (char.class?.toLowerCase() === 'replicant') {
    const b = BUILDINGS.find(bb => bb.id === 'machine_bunker')!;
    return { x: b.x + b.w / 2, y: b.y + b.h + 20, buildingId: 'machine_bunker' };
  }
  if (housingTier && housingTier !== 'shelter') {
    const tier = HOUSING_TIERS.find(t => t.id === housingTier);
    if (tier) {
      const b = BUILDINGS.find(bb => bb.id === tier.building);
      if (b) return { x: b.x + b.w / 2, y: b.y + b.h + 20, buildingId: tier.building };
    }
  }
  const bid = UNEMPLOYED_SPAWN_BUILDINGS[Math.floor(Math.random() * UNEMPLOYED_SPAWN_BUILDINGS.length)];
  const b = BUILDINGS.find(bb => bb.id === bid)!;
  return { x: b.x + b.w / 2, y: b.y + b.h + 20, buildingId: bid };
}

function getHamletLabel(bid: string): string {
  const b = BUILDINGS.find(bb => bb.id === bid);
  return b?.label ?? 'SHELTER';
}

// ── INTRO STORY CINEMATIC ──────────────────────────────────────────────────────
const INTRO_LINES = [
  'YEAR 2047.',
  '',
  'THE CORPO WARS ARE OVER.',
  'PABLO CORP WON.',
  '',
  'MINX CITY IS THEIR CROWN JEWEL —',
  'A VERTICAL MEGALOPOLIS BUILT ON DEBT,',
  'SURVEILLANCE, AND HUSTLE.',
  '',
  'EVERYONE OWES SOMETHING.',
  'EVERYONE WORKS.',
  'EVERYONE GETS RATED.',
  '',
  'YOU JUST ARRIVED.',
  '',
  'YOUR INTAKE CHIP WAS SCANNED AT THE CHECKPOINT.',
  'YOUR CREDIT SCORE WAS LOGGED.',
  'YOUR MISSION ASSIGNMENT IS PENDING.',
  '',
  'FIND A TERMINAL.',
  'AN AI NAMED PABLO WILL HANDLE YOUR INTAKE.',
  '',
  'EVERYTHING YOU NEED — FOOD, GEAR, A ROOF —',
  'COMES OUT OF A VENDING MACHINE.',
  'EVEN REAL ESTATE. NO SHOPKEEPERS.',
  'NO REALTORS. JUST THE MACHINES.',
  '',
  'LEARN TO USE THEM. THEY ARE THE CITY.',
  '',
  `GOOD LUCK, ${salarymanTerm(getSalarymanGender(), 'upper')}.`,
  'YOU\'LL NEED IT.',
];

function IntroStoryCinematic({ charName, onFinish }: { charName: string; onFinish: () => void }) {
  const [lineIdx, setLineIdx] = useState(0);
  const [displayed, setDisplayed] = useState('');
  const [charIdx, setCharIdx] = useState(0);
  const [done, setDone] = useState(false);
  const [blink, setBlink] = useState(true);
  useEffect(() => { const t = setInterval(() => setBlink(b => !b), 400); return () => clearInterval(t); }, []);

  // Background music intentionally disabled — the user controls all sound
  // via the audio settings / music player. Auto-looping a track during the
  // intro cinematic bypassed every volume control, so it's been removed.

  useEffect(() => {
    if (done) return;
    const line = INTRO_LINES[lineIdx] ?? '';
    if (charIdx < line.length) {
      const t = setTimeout(() => {
        setDisplayed(prev => prev + line[charIdx]);
        setCharIdx(c => c + 1);
      }, line === '' ? 0 : 28);
      return () => clearTimeout(t);
    } else {
      const delay = line === '' ? 300 : 900;
      const t = setTimeout(() => {
        if (lineIdx < INTRO_LINES.length - 1) {
          setLineIdx(i => i + 1);
          setDisplayed('');
          setCharIdx(0);
        } else {
          setDone(true);
        }
      }, delay);
      return () => clearTimeout(t);
    }
  }, [lineIdx, charIdx, done]);

  const skip = () => {
    try { localStorage.setItem('sm_intro_seen', '1'); } catch {}
    onFinish();
  };

  const VT: React.CSSProperties = { fontFamily: "'VT323', monospace" };
  const ST: React.CSSProperties = { fontFamily: "'Share Tech Mono', monospace" };

  return (
    <div style={{
      position: 'fixed', inset: 0, zIndex: 9999,
      background: '#000', display: 'flex', flexDirection: 'column',
      alignItems: 'center', justifyContent: 'center',
    }}>
      <div style={{ maxWidth: 520, width: '90%', textAlign: 'center', padding: '2rem' }}>
        <div style={{ marginBottom: '1.5rem', ...VT, fontSize: '1.1rem', color: 'rgba(56,189,248,0.3)', letterSpacing: '.2em' }}>
          PABLO CORP — CLASSIFIED BRIEFING
        </div>
        <div style={{ minHeight: 320, display: 'flex', flexDirection: 'column', gap: '.6rem', justifyContent: 'center' }}>
          {INTRO_LINES.slice(0, lineIdx).map((l, i) => (
            <div key={i} style={{ ...VT, fontSize: '1.35rem', color: l === '' ? 'transparent' : 'rgba(56,189,248,0.75)', letterSpacing: '.1em', lineHeight: 1.3 }}>
              {l || '\u00A0'}
            </div>
          ))}
          {lineIdx < INTRO_LINES.length && (
            <div style={{ ...VT, fontSize: '1.35rem', color: '#38bdf8', letterSpacing: '.1em', lineHeight: 1.3 }}>
              {displayed}<span style={{ opacity: blink ? 1 : 0 }}>█</span>
            </div>
          )}
        </div>
        {done && (
          <div style={{ marginTop: '2rem', display: 'flex', flexDirection: 'column', gap: '.8rem', alignItems: 'center' }}>
            <div style={{ ...VT, fontSize: '1.2rem', color: 'rgba(56,189,248,0.5)', letterSpacing: '.15em' }}>
              {salarymanTerm(getSalarymanGender(), 'upper')} {charName.toUpperCase()} — STANDING BY
            </div>
            <button onClick={skip} style={{
              ...VT, fontSize: '1.1rem', letterSpacing: '.15em',
              padding: '.5rem 2rem', background: 'rgba(56,189,248,0.1)',
              border: '1px solid rgba(56,189,248,0.6)', color: '#38bdf8',
              cursor: 'pointer',
            }}>
              BEGIN INTAKE ▸
            </button>
          </div>
        )}
        {!done && (
          <button onClick={skip} style={{
            marginTop: '2.5rem', ...ST, fontSize: '.65rem', letterSpacing: '.12em',
            padding: '.25rem .8rem', background: 'transparent',
            border: '1px solid rgba(56,189,248,0.2)', color: 'rgba(56,189,248,0.3)',
            cursor: 'pointer',
          }}>
            SKIP ▸
          </button>
        )}
      </div>
    </div>
  );
}

function createFirstMission(char: Char): Quest | null {
  const termB = BUILDINGS.find(b => b.id === 'term_central') ?? BUILDINGS.find(b => b.id.startsWith('term_'));
  const termFallback = termB ?? { x: 6380, y: 5970, w: 18, h: 24 };
  return {
    id: 'find_terminal',
    title: 'FIND A TERMINAL',
    description: 'Your intake chip was scanned at the checkpoint but you have not been processed. Find a public terminal anywhere in Minx City and connect. An AI named PABLO will handle your intake remotely. Look for terminals marked on your map — small kiosks with green screens.',
    completed: false,
    tasks: [
      { id: 'open_terminal', label: 'Find and use a public terminal', done: false, mapMarker: { x: termFallback.x + termFallback.w / 2, y: termFallback.y + termFallback.h / 2, label: 'PUBLIC TERMINAL' } },
    ],
  };
}

function createEstablishBusinessMission(char: Char): Quest | null {
  if (char.bizType === 'unemployed' || !char.hasBusiness) return null;
  const towerB = BUILDINGS.find(b => b.id === 'pablo_tower') ?? { id: 'pablo_tower', x: 1400, y: 400, w: 200, h: 200, label: 'SHADOW TOWER' } as (typeof BUILDINGS)[0];
  const storeB = BUILDINGS.find(b => b.id === 'pablo_store') ?? towerB;
  const wsB = char.workstation ? BUILDINGS.find(b => b.id === char.workstation) : null;
  const wsFallback = wsB ?? towerB;
  return {
    id: 'establish_business',
    title: 'ESTABLISH YOUR BUSINESS',
    description: `Set up your ${char.company} operation in Minx City. Customize your workspace, get signage, and prepare for business.`,
    completed: false,
    tasks: [
      { id: 'visit_workstation', label: `Visit your workstation at ${char.workstationLabel ?? 'assigned location'}`, done: false, mapMarker: { x: wsFallback.x + wsFallback.w / 2, y: wsFallback.y + wsFallback.h / 2, label: wsB ? 'WORKSTATION' : 'SHADOW TOWER' } },
      { id: 'visit_tower', label: 'Register at SHADOW TOWER (PABLO CORP HQ)', done: false, mapMarker: { x: towerB.x + towerB.w / 2, y: towerB.y + towerB.h / 2, label: 'SHADOW TOWER' } },
      { id: 'get_device', label: 'Pick up your PABLO CORP device from the PABLO CORP store', done: false, mapMarker: { x: storeB.x + storeB.w / 2, y: storeB.y + storeB.h / 2, label: 'PABLO CORP STORE' } },
      { id: 'customize_costume', label: `Customize your ${salarymanTerm(getSalarymanGender())} appearance`, done: false, mapMarker: { x: towerB.x + towerB.w / 2, y: towerB.y + towerB.h / 2, label: 'SHADOW TOWER' } },
      { id: 'setup_signage', label: 'Set up business signage (visit your workstation office)', done: false, mapMarker: { x: wsFallback.x + wsFallback.w / 2, y: wsFallback.y + wsFallback.h / 2, label: wsB ? 'SIGNAGE' : 'SHADOW TOWER' } },
      { id: 'pablo_auto', label: '(Optional) Use PABLO to automate business setup', done: false, mapMarker: { x: storeB.x + storeB.w / 2, y: storeB.y + storeB.h / 2, label: 'PABLO CORP STORE' } },
    ],
  };
}

function createStarterMissions(): Quest[] {
  const clinicB = BUILDINGS.find(b => b.id === 'clinic');
  const arcadeB = BUILDINGS.find(b => b.id === 'arcade');
  const noodleB = BUILDINGS.find(b => b.id === 'noodle_bar');
  const storeB = BUILDINGS.find(b => b.id === 'pablo_store');
  const missions: Quest[] = [];
  if (clinicB) {
    missions.push({
      id: 'starter_explore_clinic',
      title: 'FIND THE CLINIC',
      description: 'The city can be dangerous. Locate the CLINIC in case you need medical attention.',
      completed: false,
      tasks: [
        { id: 'visit_clinic', label: 'Visit the CLINIC', done: false, mapMarker: { x: clinicB.x + clinicB.w / 2, y: clinicB.y + clinicB.h / 2, label: 'CLINIC' } },
      ],
    });
  }
  if (noodleB) {
    missions.push({
      id: 'starter_noodle_run',
      title: 'GRAB A MEAL',
      description: 'Your hunger is dropping. Find the NOODLE BAR and grab something to eat before your stats suffer.',
      completed: false,
      tasks: [
        { id: 'visit_noodle', label: 'Visit the NOODLE BAR', done: false, mapMarker: { x: noodleB.x + noodleB.w / 2, y: noodleB.y + noodleB.h / 2, label: 'NOODLE BAR' } },
      ],
    });
  }
  if (arcadeB || storeB) {
    const target = arcadeB ?? storeB!;
    missions.push({
      id: 'starter_explore_city',
      title: 'EXPLORE THE CITY',
      description: 'Get your bearings. Find a point of interest in Minx City and see what it offers.',
      completed: false,
      tasks: [
        { id: 'visit_poi', label: `Visit ${target.label}`, done: false, mapMarker: { x: target.x + target.w / 2, y: target.y + target.h / 2, label: target.label } },
      ],
    });
  }
  return missions;
}

