                  g.dogCompanion.hp = DOG_MAX_HP;
                  g.dogCompanion.maxHp = DOG_MAX_HP;
                  g.dogCompanion.x = stray.x;
                  g.dogCompanion.y = stray.y;
                  g.dogCompanion.injured = false;
