              <button onClick={() => { setChatOpen(false); chatOpenRef.current = false; setShowDmPicker(false); }} style={{ fontSize: '.55rem', color: 'rgba(56,189,248,.3)', border: 'none', background: 'transparent', cursor: 'pointer' }}>✕</button>
